            if (mutualFundSipData.TriggerPriceOption.IsSet)
                if (mutualFundSipData.TriggerPriceOption.Value != null)
                    writer.WriteNumber("trigger_price", mutualFundSipData.TriggerPriceOption.Value!.Value);
                else
                    writer.WriteNull("trigger_price");

            if (mutualFundSipData.SipTypeOption.IsSet)
                if (mutualFundSipData.SipTypeOption.Value != null)
                    writer.WriteString("sip_type", mutualFundSipData.SipType);
                else
                    writer.WriteNull("sip_type");
        }
    }
}
